-- Pequenos Contos · Supabase schema
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','subscriber');
create type public.subscription_plan as enum ('monthly','quarterly','annual');
create type public.story_status as enum ('draft','published');
create type public.text_position as enum ('top','center','bottom');
create table public.subscribers(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique references auth.users(id) on delete cascade,email text not null unique,secret_hash text not null,plan public.subscription_plan not null default 'monthly',starts_at timestamptz not null default now(),expires_at timestamptz not null,status text not null default 'active' check(status in ('active','inactive')),created_at timestamptz not null default now());
create table public.sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,token_hash text not null,device text,created_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),revoked_at timestamptz);
create unique index one_live_session_per_user on public.sessions(user_id) where revoked_at is null;
create table public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade,role public.app_role not null default 'subscriber');
create table public.child_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,age_range text not null check(age_range in ('0-1','1-2','2-3','3-5')),avatar text not null default '🐻',created_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz default now());
create table public.stories(id uuid primary key default gen_random_uuid(),title text not null,age_range text not null check(age_range in ('0-1','1-2','2-3','3-5')),category_id uuid references public.categories(id),summary text not null default '',lesson text not null default '',reading_minutes int not null default 4,cover_path text,is_free boolean not null default false,status public.story_status not null default 'draft',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.story_pages(id uuid primary key default gen_random_uuid(),story_id uuid not null references public.stories(id) on delete cascade,sort_order int not null,text text not null default '',image_path text not null,text_position public.text_position not null default 'bottom',overlay boolean not null default true,font_size text not null default 'large' check(font_size in ('small','medium','large')),text_color text not null default 'light' check(text_color in ('light','dark')),unique(story_id,sort_order));
create table public.story_questions(id uuid primary key default gen_random_uuid(),story_id uuid not null references public.stories(id) on delete cascade,sort_order int not null,question text not null);
create table public.reads(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.child_profiles(id) on delete cascade,story_id uuid not null references public.stories(id) on delete cascade,last_page int not null default -1,completed_at timestamptz,updated_at timestamptz default now(),unique(profile_id,story_id));
create table public.favorites(profile_id uuid not null references public.child_profiles(id) on delete cascade,story_id uuid not null references public.stories(id) on delete cascade,created_at timestamptz default now(),primary key(profile_id,story_id));
create table public.reading_streaks(profile_id uuid primary key references public.child_profiles(id) on delete cascade,current_days int not null default 0,last_read_date date,updated_at timestamptz default now());
create table public.payment_customers(id uuid primary key default gen_random_uuid(),subscriber_id uuid not null references public.subscribers(id) on delete cascade,provider text,provider_customer_id text,created_at timestamptz default now());
create table public.payment_events(id uuid primary key default gen_random_uuid(),subscriber_id uuid references public.subscribers(id) on delete set null,provider text,provider_event_id text unique,payload jsonb,processed_at timestamptz,created_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin'); $$;
create or replace function public.owns_profile(pid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.child_profiles where id=pid and user_id=auth.uid()); $$;
alter table public.subscribers enable row level security; alter table public.sessions enable row level security; alter table public.user_roles enable row level security; alter table public.child_profiles enable row level security; alter table public.categories enable row level security; alter table public.stories enable row level security; alter table public.story_pages enable row level security; alter table public.story_questions enable row level security; alter table public.reads enable row level security; alter table public.favorites enable row level security; alter table public.reading_streaks enable row level security; alter table public.payment_customers enable row level security; alter table public.payment_events enable row level security;
create policy "admin manage subscribers" on public.subscribers for all using(public.is_admin()) with check(public.is_admin());
create policy "admin manage sessions" on public.sessions for all using(public.is_admin()) with check(public.is_admin());
create policy "admin manage roles" on public.user_roles for all using(public.is_admin()) with check(public.is_admin());
create policy "users read own role" on public.user_roles for select using(user_id=auth.uid());
create policy "profiles own access" on public.child_profiles for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "categories visible" on public.categories for select using(true);
create policy "admin categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "published or admin stories" on public.stories for select using((status='published' and (is_free or exists(select 1 from public.subscribers s where s.auth_user_id=auth.uid() and s.status='active' and s.expires_at>now()))) or public.is_admin());
create policy "admin manage stories" on public.stories for all using(public.is_admin()) with check(public.is_admin());
create policy "pages visible with story" on public.story_pages for select using(exists(select 1 from public.stories s where s.id=story_id and ((s.status='published' and (s.is_free or exists(select 1 from public.subscribers sub where sub.auth_user_id=auth.uid() and sub.status='active' and sub.expires_at>now()))) or public.is_admin())));
create policy "admin manage pages" on public.story_pages for all using(public.is_admin()) with check(public.is_admin());
create policy "questions visible with story" on public.story_questions for select using(exists(select 1 from public.stories s where s.id=story_id and s.status='published'));
create policy "admin manage questions" on public.story_questions for all using(public.is_admin()) with check(public.is_admin());
create policy "own reads" on public.reads for all using(public.owns_profile(profile_id) or public.is_admin()) with check(public.owns_profile(profile_id) or public.is_admin());
create policy "own favorites" on public.favorites for all using(public.owns_profile(profile_id) or public.is_admin()) with check(public.owns_profile(profile_id) or public.is_admin());
create policy "own streaks" on public.reading_streaks for all using(public.owns_profile(profile_id) or public.is_admin()) with check(public.owns_profile(profile_id) or public.is_admin());
create policy "admin payments" on public.payment_customers for all using(public.is_admin()) with check(public.is_admin());
create policy "admin payment events" on public.payment_events for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('story-art','story-art',false,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "admin upload story art" on storage.objects for insert to authenticated with check(bucket_id='story-art' and public.is_admin());
create policy "admin update story art" on storage.objects for update to authenticated using(bucket_id='story-art' and public.is_admin());
create policy "story art read published" on storage.objects for select to authenticated using(bucket_id='story-art' and (public.is_admin() or exists(select 1 from public.stories s where (s.cover_path=name or exists(select 1 from public.story_pages p where p.story_id=s.id and p.image_path=name)) and s.status='published' and (s.is_free or exists(select 1 from public.subscribers sub where sub.auth_user_id=auth.uid() and sub.status='active' and sub.expires_at>now())))));
-- IMPORTANT: secret_hash uses bcrypt/crypt in Edge Function; never expose this table to subscribers.
